import { expect, sample, test, uniqueName } from "../../fixtures";

test.describe("Review vendors", () => {
  test(
    "submitting with missing documents lists what is missing",
    { tag: "@REV-02" },
    async ({ apiAs }) => {
      // Arrange: a draft vendor with only an extracted w9 document
      const member = await apiAs("member");

      const vendorResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV02 Missing Docs"),
          category: "services",
          contact_email: "billing@rev02-missing.test",
        },
      });
      expect(vendorResponse.status()).toBe(201);
      const vendor = await vendorResponse.json();
      expect(vendor.status).toBe("draft");

      const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.pdf",
            mimeType: "application/pdf",
            buffer: Buffer.from("%PDF-1.4 rev02 w9 test document"),
          },
        },
      });
      expect(uploadResponse.status()).toBe(201);
      const document = await uploadResponse.json();

      // Wait for extraction to finish so the w9 is in the "extracted" state.
      await expect
        .poll(
          async () => {
            const response = await member.get(`/api/documents/${document.id}`);
            return ((await response.json()) as { status: string }).status;
          },
          { timeout: 60_000, message: "w9 document should reach extracted" },
        )
        .toBe("extracted");

      // Act
      const response = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Assert
      expect(response.status()).toBe(409);
      const body = await response.json();
      expect(body.error.code).toBe("documents_incomplete");

      // The missing kinds must be reported somewhere in the error payload.
      const serialized = JSON.stringify(body);
      expect(serialized).toContain("contract");
      expect(serialized).toContain("insurance_certificate");
      expect(serialized).not.toContain('"w9"]');
    },
  );
});
